import * as M from './model.js';
import * as S from './supplies.js';
import * as O from './school-operations.js';
import * as A from './academic-year.js';
export function place(s,itemId,quantity){const g=S.getGood(itemId),q=Number(quantity),orders=O.data(s).orders;if(!g||!Number.isInteger(q)||q<1||q>10)return {error:'물품과 1~10묶음 수량을 선택해 주세요.'};if(!g.consumable&&(q>1||S.stock(s,itemId)>0||orders.some(o=>o.itemId===itemId&&o.remaining>0)))return {error:'재사용 교구는 중복 주문하지 않습니다.'};const cost=g.cost*q;if(s.budget<cost)return {error:'학습준비물비 잔액이 부족합니다.'};s.budget-=cost;orders.push({id:'order-'+s.academic.year+'-'+orders.length,itemId,quantity:q,remaining:q,received:0,refunded:0,cost,day:s.day,due:(s.academic.calendar.filter(d=>d.school&&d.day>s.day)[(s.config.region==='island'?3:s.config.region==='mountain'?2:1)-1]?.day??s.academic.end),status:'ordered',history:[{date:M.stamp(s),text:q+'묶음 주문·예산 배정'}]});return {ok:true};}
export function receive(s,id,quantity){const o=O.data(s).orders.find(o=>o.id===id),q=Number(quantity);if(!o||s.day<o.due||!Number.isInteger(q)||q<1||q>o.remaining)return {error:'입고 예정일과 남은 주문 수량을 확인해 주세요.'};const g=S.getGood(o.itemId);o.remaining-=q;o.received+=q;S.inventory(s)[g.id]=S.stock(s,g.id)+q*g.pack;s.purchases.push({id:g.id,price:g.cost*q,label:g.name,quantity:q,day:s.day,minute:s.minute,date:M.stamp(s),orderId:id});o.status=o.remaining?'partial':'completed';o.history.push({date:M.stamp(s),text:q+'묶음 검수·입고'});return {ok:true};}
export function cancel(s,id){const o=O.data(s).orders.find(o=>o.id===id);if(!o||!o.remaining)return {error:'환불할 미입고 수량이 없습니다.'};const g=S.getGood(o.itemId);s.budget+=o.remaining*g.cost;o.refunded+=o.remaining;o.history.push({date:M.stamp(s),text:o.remaining+'묶음 취소·환불'});o.remaining=0;o.status=o.received?'completed':'cancelled';return {ok:true};}
export function valid(s){const orders=s.operations?.orders;return !orders||Array.isArray(orders)&&orders.every(o=>S.getGood(o.itemId)&&o.cost===S.getGood(o.itemId).cost*o.quantity&&Number.isInteger(o.due)&&o.due>=o.day&&o.due<=s.academic.end&&[o.quantity,o.remaining,o.received,o.refunded].every(n=>Number.isInteger(n)&&n>=0)&&o.quantity>0&&o.quantity<=10&&o.quantity===o.remaining+o.received+o.refunded&&Array.isArray(o.history));}
